SELECT qryTakeOff_A.CaseID, qryTakeOff_A.FileNumber, qryTakeOff_A.Name, qryTakeOff_A.Last_Name, qryTakeOff_A.Orig_Atty, qryTakeOff_A.Matter_type, qryTakeOff_A.HandlingAtty_Case, qryTakeOff_A.SumOfAdvancedAR, qryTakeOff_A.CostHold, qryTakeOff_A.SumOfUnclearedDeposits, qryTakeOff_A.Balance, qryTakeOff_A.SumOfUncashedChecks, [Balance]-Nz([SumOfUnclearedDeposits],0) AS AvailBalance, [Balance]+Nz([SumOfUncashedChecks],0)-Nz([SumOfUnclearedDeposits],0) AS BankBalance, qryTakeOff_A.SumOfTotal, qryTakeOff_A.IANumber, qryTakeOff_A.Bill_ID, qryTakeOff_A.SumOfCostBalance, qryTakeOff_A.SumofPrepaid, qryTakeOff_A.SumAdvLegal, qryTakeOff_A.SumCostReimb, qryTakeOff_A.SumEarnedAdv, IIf(Nz([CostHold],0)-Nz([SumofCostBalance],0)>0,Nz([CostHold],0)-Nz([SumofCostBalance],0)) AS CostHoldBalance, Nz([SumAdvLegal],0)-Nz([SumEarnedAdv],0) AS AdvLegalBalance, Nz([SumofPrepaid],0)-Nz([SumCostReimb],0) AS AdvCostBalance
FROM qryTakeOff_A
WHERE ((([Balance]-Nz([SumOfUnclearedDeposits],0))<>0)) OR ((([Balance]+Nz([SumOfUncashedChecks],0)-Nz([SumOfUnclearedDeposits],0))<>0)) OR (((qryTakeOff_A.SumOfUnclearedDeposits)<>0)) OR (((qryTakeOff_A.SumOfUncashedChecks)<>0)) OR (((qryTakeOff_A.SumOfTotal)<>0))
ORDER BY qryTakeOff_A.Name;